#include "liveMedia.hh"
#include "BasicUsageEnvironment.hh"
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <cstdio>
#include <cstring>
struct Run {FramedSource* source;TaskScheduler* scheduler;unsigned char out[256];unsigned char got[2];unsigned n=0;EventLoopWatchVariable stop{0};};
static void frame(void* p,unsigned size,unsigned trunc,timeval,unsigned){Run& r=*(Run*)p;if(size!=2||trunc||r.n>=2){r.stop=2;return;}r.got[r.n++]=r.out[1];if(r.n==2)r.stop=1;else r.source->getNextFrame(r.out,sizeof(r.out),frame,&r,NULL,NULL);}
static void timeout(void* p){((Run*)p)->stop=3;}
static bool sendpacket(int fd,sockaddr_in const& dest,unsigned pt,unsigned seq,unsigned ssrc,unsigned char value,bool rtx){unsigned char p[16]={0x80,(unsigned char)(0x80|pt),(unsigned char)(seq>>8),(unsigned char)seq,0,0,0x23,0x28,(unsigned char)(ssrc>>24),(unsigned char)(ssrc>>16),(unsigned char)(ssrc>>8),(unsigned char)ssrc};unsigned n=12;if(rtx){p[n++]=0;p[n++]=101;}p[n++]=0x65;p[n++]=value;return sendto(fd,p,n,0,(sockaddr*)&dest,sizeof(dest))==(int)n;}
int main(){TaskScheduler* scheduler=BasicTaskScheduler::createNew();UsageEnvironment* env=BasicUsageEnvironment::createNew(*scheduler);char const* sdp="v=0\r\no=- 1 1 IN IP4 127.0.0.1\r\ns=local\r\nt=0 0\r\nc=IN IP4 127.0.0.1\r\nm=video 0 RTP/AVP 96 97\r\na=rtpmap:96 H264/90000\r\na=fmtp:96 packetization-mode=1\r\na=rtpmap:97 rtx/90000\r\na=fmtp:97 apt=96\r\na=ssrc-group:FID 1111 2222\r\n";MediaSession* session=MediaSession::createNew(*env,sdp);if(!session)return 2;MediaSubsessionIterator it(*session);MediaSubsession* sub=it.next();if(!sub||!sub->initiate())return 3;sub->rtpSource()->setPacketReorderingThresholdTime(0);int fd=socket(AF_INET,SOCK_DGRAM,0);if(fd<0)return 4;sockaddr_in dest{};dest.sin_family=AF_INET;dest.sin_addr.s_addr=htonl(INADDR_LOOPBACK);dest.sin_port=htons(sub->clientPortNum());if(!sendpacket(fd,dest,96,100,1111,0xaa,false)||!sendpacket(fd,dest,97,5000,2222,0xbb,true)||!sendpacket(fd,dest,96,102,1111,0xcc,false))return 5;Run run;run.source=sub->readSource();run.scheduler=scheduler;run.source->getNextFrame(run.out,sizeof(run.out),frame,&run,NULL,NULL);TaskToken token=scheduler->scheduleDelayedTask(1000000,timeout,&run);scheduler->doEventLoop(&run.stop);scheduler->unscheduleDelayedTask(token);printf("primary_pt=%u codec=%s frames=%u bytes=%02x,%02x\n",sub->rtpPayloadFormat(),sub->codecName(),run.n,run.got[0],run.got[1]);printf("rtx_recovered=%s\n",run.n==2&&run.got[1]==0xbb?"true":"false");bool ok=run.n==2&&run.got[0]==0xaa&&run.got[1]==0xcc;Medium::close(session);close(fd);env->reclaim();delete scheduler;return ok?0:6;}
